// Prepare Gemini Audio Payload for Algerian Darija
const binaryData = items[0].binary?.data;
if (!binaryData) {
  throw new Error('No audio/video file provided in binary property "data"');
}

const base64Audio = binaryData.data;
const mimeType = binaryData.mimeType || 'audio/mp3';
const query = $input.item.json.query || {};
const dialect = query.dialect || 'General Algerian';

const prompt = `You are an expert transcriber specialized in Algerian Arabic (الدارجة الجزائرية - Darija).\nListen to the audio and transcribe accurately with exact word timestamps.\nDialect: ${dialect}.\nIMPORTANT: Do NOT write French loanwords phonetically in awkward Arabic letters (e.g. avoid 'برومي لو تيست'). If speaker uses standard French words (e.g. 'premier test', 'rendez-vous', 'projet', 'voiture', 'normal'), write them cleanly in standard French or natural Algerian terms.\nReturn STRICT JSON format only:\n{\n  "language": "ar-DZ",\n  "text": "...",\n  "segments": [\n    {\n      "id": 0,\n      "start": 0.00,\n      "end": 2.50,\n      "text": "واش راك خويا",\n      "words": [\n        {"word": "واش", "start": 0.00, "end": 0.60},\n        {"word": "راك", "start": 0.60, "end": 1.20},\n        {"word": "خويا", "start": 1.20, "end": 2.50}\n      ]\n    }\n  ]\n}`;

return [{
  json: {
    contents: [
      {
        parts: [
          {
            inline_data: {
              mime_type: mimeType,
              data: base64Audio
            }
          },
          {
            text: prompt
          }
        ]
      }
    ],
    generationConfig: {
      temperature: 0.2,
      responseMimeType: 'application/json'
    },
    query: query
  }
}];

// Parse Gemini Response and Build Animated ASS Subtitles with Strict Script-Separated Chunking & Silence Cutoff
const response = $input.item.json;
const candidates = response.candidates || [];
if (!candidates.length) {
  throw new Error('Gemini API returned no candidates');
}

const rawText = candidates[0].content?.parts?.[0]?.text || '{}';
let data = {};
try {
  data = JSON.parse(rawText);
} catch (e) {
  const clean = rawText.replace(/```json/g, '').replace(/```/g, '').trim();
  data = JSON.parse(clean);
}

const segments = data.segments || [];

// 1. Darija Spelling Normalizer
function sanitizeDarijaText(text) {
  if (!text) return "";
  return text
    .replace(/\bهكذاء\b/g, "هكذا")
    .replace(/\bهكداء\b/g, "هكدا")
    .replace(/\bهاكداء\b/g, "هاكدا")
    .replace(/\bهاكذاء\b/g, "هاكذا")
    .replace(/\bخلاصء\b/g, "خلاص")
    .replace(/\bصحاء\b/g, "صحة");
}

// 2. Darija Prefix Tokenizer: Binds orphaned articles and imperfective verb prefixes (يـ, تـ, نـ, الـ, etc.)
const ARABIC_PREFIX_ARTICLE_REGEX = /^(?:[\u0648\u0641\u0628\u0643]?[\u0622\u0623\u0625\u0627]?[\u0644][\u0640\-]*|[\u0648\u0641\u0628]?[\u0644][\u0644][\u0640\-]*|[\u0648\u0641\u0628]?[\u0644][\u0640\-]+|[\u0648]?[\u0644][\u0627][\u0640\-]*|[\u0648]?[\u0644][\u0648][\u0640\-]*|[\u0648]?[\u0644][\u064a][\u0640\-]*|[\u0648]?[\u0627][\u0644][\u0644][\u064a][\u0640\-]*|[\u0648]?[\u062f][\u064a][\u0640\-]*|[\u0648]?[\u062f][\u0648][\u0640\-]*|[\u0648]?[\u062f][\u0640\-]+|[\u0648]?[\u0628\u0641\u0643][\u0640\-]+|[\u0648]?[\u064a\u062a\u0646][\u0640\-]+|[\u0648]?[\u0645][\u0627][\u0640\-]*|[\u0648]?[\u064a][\u0627][\u0640\-]*|[\u0648]?[\u0647][\u0627][\u0640\-]*|[\u0628\u0641]?[\u0647][\u0627][\u062f][\u0640\-]*)$/;

function isPrefixToken(token, nextToken) {
  const clean = String(token || '').replace(/^[^\w\u0600-\u06FF]+|[^\w\u0600-\u06FF]+$/g, '').trim();
  if (!clean) return false;
  if (ARABIC_PREFIX_ARTICLE_REGEX.test(clean) || String(token || '').trim().endsWith('-') || String(token || '').trim().endsWith('ـ')) return true;
  if (["ي", "ت", "ن"].includes(clean) && nextToken && /[a-zA-Z]/.test(nextToken)) return true;
  return false;
}

function classifyScript(token) {
  if (/[a-zA-Z]/.test(token)) return "latin";
  if (/[\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF]/.test(token)) return "arabic";
  return "arabic";
}

function bindArabicArticles(words) {
  if (!words || !words.length) return [];
  const bound = [];
  let i = 0;
  while (i < words.length) {
    const w = words[i];
    const textVal = sanitizeDarijaText(String(w.word || '').trim());
    const nextWText = i + 1 < words.length ? String(words[i + 1].word || '').trim() : undefined;
    if (isPrefixToken(textVal, nextWText) && i + 1 < words.length) {
      const chain = [w];
      let j = i + 1;
      while (j < words.length) {
        const futureWText = j + 1 < words.length ? String(words[j + 1].word || '').trim() : undefined;
        if (isPrefixToken(words[j].word || '', futureWText)) {
          chain.push(words[j]);
          j++;
        } else {
          break;
        }
      }
      if (j < words.length) {
        const targetWord = words[j];
        const jointText = chain.map(item => sanitizeDarijaText(String(item.word || '').trim())).join(' ') + ' ' + sanitizeDarijaText(String(targetWord.word || '').trim());
        bound.push({
          word: jointText.trim(),
          start: chain[0].start,
          end: targetWord.end || (targetWord.start + 0.3)
        });
        i = j + 1;
        continue;
      } else {
        const nextW = words[i + 1];
        bound.push({
          word: `${textVal} ${sanitizeDarijaText(String(nextW.word || '').trim())}`,
          start: w.start,
          end: nextW.end || (nextW.start + 0.3)
        });
        i += 2;
        continue;
      }
    }
    bound.push({
      ...w,
      word: textVal
    });
    i++;
  }
  return bound;
}

// 3. Strict Script-Separated Chunking (Arabic and French never mix on screen)
const NON_TERMINAL_PARTICLES = new Set([
  "و", "ف", "ب", "ل", "في", "على", "من", "عن", "مع", "إلى", "الى",
  "ما", "لا", "لي", "اللي", "دي", "دو", "يا", "ها", "بهاد", "فهاد", "هاد",
  "la", "le", "les", "un", "une", "des", "du", "de", "d'", "et", "ou",
  "en", "au", "aux", "par", "pour", "avec", "dans", "sur"
]);

function isNonTerminal(token) {
  const clean = (token || "").replace(/^[^\w\u0600-\u06FF]+|[^\w\u0600-\u06FF]+$/g, "").toLowerCase().trim();
  return NON_TERMINAL_PARTICLES.has(clean) || (token || "").trim().endsWith("-") || (token || "").trim().endsWith("ـ");
}

function balanceChunkSizes(totalWords, targetSize) {
  const effectiveTarget = Math.min(4, Math.max(2, targetSize || 3));
  if (totalWords <= effectiveTarget) return [totalWords];
  const numChunks = Math.ceil(totalWords / effectiveTarget);
  if (totalWords % effectiveTarget === 1 && numChunks > 1) {
    const baseSize = Math.floor(totalWords / numChunks);
    const remainder = totalWords % numChunks;
    return Array.from({ length: numChunks }, (_, k) => Math.min(4, baseSize + (k < remainder ? 1 : 0)));
  }
  const sizes = [];
  let remaining = totalWords;
  while (remaining > 0) {
    if (remaining === effectiveTarget + 1) {
      const half = Math.floor(remaining / 2);
      sizes.push(Math.min(4, remaining - half));
      sizes.push(Math.min(4, half));
      break;
    }
    const take = Math.min(4, Math.min(effectiveTarget, remaining));
    sizes.push(take);
    remaining -= take;
  }
  return sizes;
}

function formatAssTime(seconds) {
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  const s = Math.floor(seconds % 60);
  const cs = Math.floor((seconds % 1) * 100);
  return `${h}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}.${String(cs).padStart(2, '0')}`;
}

let assContent = `[Script Info]\nTitle: DZ Subtitles AI\nScriptType: v4.00+\nPlayResX: 1080\nPlayResY: 1920\n\n[V4+ Styles]\nFormat: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding\nStyle: Default,Cairo,56,&H00FFFFFF,&H0000E6FF,&H00000000,&H00000000,-1,0,0,0,100,100,0,0,1,3.5,2.0,2,30,30,420,-1\n\n[Events]\nFormat: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\n`;

const TARGET_WORDS_PER_CHUNK = 3;

// Collect and flatten all words with bound prefixes
const allWords = [];
for (const seg of segments) {
  let segWords = seg.words || [];
  if (!segWords.length && seg.text) {
    const ws = seg.text.trim().split(/\s+/);
    const dur = Math.max(0.3, (seg.end - seg.start) / ws.length);
    let cur = seg.start;
    segWords = ws.map((w, i) => ({ word: w, start: cur + i * dur, end: cur + (i + 1) * dur }));
  }
  const boundWords = bindArabicArticles(segWords);
  allWords.push(...boundWords);
}

// Partition into homogeneous script runs and pause blocks
const runs = [];
let currentRun = [];
let currentScript = null;

for (const w of allWords) {
  const wText = String(w.word || '').trim();
  if (!wText) continue;
  const tokenScript = classifyScript(wText);

  if (currentRun.length > 0) {
    const prev = currentRun[currentRun.length - 1];
    const pauseGap = w.start - (prev.end || prev.start + 0.3);
    if (tokenScript !== currentScript || pauseGap > 0.8) {
      runs.push({ words: currentRun, script: currentScript });
      currentRun = [];
      currentScript = tokenScript;
    }
  }
  if (currentRun.length === 0) {
    currentScript = tokenScript;
  }
  currentRun.push(w);
}
if (currentRun.length > 0 && currentScript) {
  runs.push({ words: currentRun, script: currentScript });
}

// Chunk each run into strictly 2-to-4 words
const chunks = [];
for (const run of runs) {
  const { words: rWords, script } = run;
  if (rWords.length <= TARGET_WORDS_PER_CHUNK) {
    chunks.push({ words: rWords, script });
    continue;
  }
  const sizes = balanceChunkSizes(rWords.length, TARGET_WORDS_PER_CHUNK);
  let offset = 0;
  for (const sz of sizes) {
    const slice = rWords.slice(offset, offset + sz);
    if (slice.length) {
      chunks.push({ words: slice, script });
    }
    offset += sz;
  }
}

// Build events with Remotion spring pop and silence cutoff
for (let cIdx = 0; cIdx < chunks.length; cIdx++) {
  const chunkObj = chunks[cIdx];
  const chunk = chunkObj.words;
  const isRtl = chunkObj.script === "arabic";
  const nextChunkStart = cIdx + 1 < chunks.length ? chunks[cIdx + 1].words[0].start : null;

  for (let j = 0; j < chunk.length; j++) {
    const active = chunk[j];
    let wEnd;
    if (j + 1 < chunk.length) {
      wEnd = chunk[j + 1].start;
    } else {
      const naturalEnd = active.end || active.start + 0.3;
      const minHold = active.start + 0.85;
      if (nextChunkStart !== null) {
        const gap = nextChunkStart - naturalEnd;
        if (gap > 0.8) {
          wEnd = Math.max(active.start + 0.3, naturalEnd + 0.35);
        } else {
          wEnd = Math.min(nextChunkStart - 0.05, Math.max(naturalEnd, minHold));
        }
      } else {
        wEnd = Math.max(naturalEnd, minHold);
      }
    }

    const startStr = formatAssTime(active.start);
    const endStr = formatAssTime(Math.max(active.start + 0.15, wEnd));
    const durMs = Math.max(120, Math.floor((wEnd - active.start) * 1000));

    // Remotion-calibrated 3-stage harmonic spring: overshoot -> recoil -> settle
    const t1 = Math.max(35, Math.min(Math.floor(durMs * 0.32), 95));
    const t2 = Math.max(t1 + 25, Math.min(Math.floor(durMs * 0.62), 185));
    const t3 = Math.max(t2 + 25, Math.min(Math.floor(durMs * 0.85), 260));

    const activePopTag = `\\c&H0000E6FF&\\fscx100\\fscy100\\t(0,${t1},0.45,\\fscx100\\fscy128)\\t(${t1},${t2},1.5,\\fscx100\\fscy112)\\t(${t2},${t3},0.85,\\fscx100\\fscy115)`;
    const normalPriTag = `\\c&H00FFFFFF&\\fscx100\\fscy100`;

    const formatted = chunk.map((w, idx) => {
      const cleanWord = isRtl ? w.word : `\\u200E${w.word}\\u200E`;
      return idx === j
        ? `{${activePopTag}}${cleanWord}{${normalPriTag}}`
        : `{${normalPriTag}}${cleanWord}`;
    }).join(' ');

    const lineText = isRtl ? `\\u200F${formatted}` : formatted;
    assContent += `Dialogue: 0,${startStr},${endStr},Default,,0,0,0,,${lineText}\n`;
  }
}

return [{
  json: {
    transcription: data,
    assContent: assContent
  }
}];
